<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRoute } from 'vue-router'
import { customerServiceApi, customerServiceMessageApi, type CustomerRagIntent } from '../api/customer-rag'

const route=useRoute(),open=ref(false),query=ref(''),intent=ref<CustomerRagIntent>('faq'),loading=ref(false),error=ref(''),messages=ref<any[]>([]),conversationId=ref(sessionStorage.getItem('customer_service_conversation_id')||crypto.randomUUID()),humanSessionId=ref(sessionStorage.getItem('customer_service_session_id')||''),poller=ref<number|undefined>(undefined)
sessionStorage.setItem('customer_service_conversation_id', conversationId.value)
function startPolling(){ if(poller.value) return; poller.value=window.setInterval(async()=>{ if(!humanSessionId.value)return; try{ const data=(await customerServiceMessageApi.messages(humanSessionId.value)).data.data||[]; messages.value=[...messages.value.filter(x=>x.role==='user'||x.sender_type),...data.map((x:any)=>({role:x.sender_type==='customer'?'user':'assistant',text:x.content,...x}))] }catch{} },2500) }
function stopPolling(){ if(poller.value)window.clearInterval(poller.value); poller.value=undefined }
const visible=computed(()=>route.path!=='/login'&&route.path!=='/register')
const options:Array<{value:CustomerRagIntent;label:string}>= [{value:'company_info',label:'公司信息'},{value:'company_business',label:'公司业务'},{value:'faq',label:'常见问题'},{value:'workflow',label:'服务流程'},{value:'policy',label:'金融政策'},{value:'risk_public',label:'风险资料'}]
async function send(){const text=query.value.trim();if(!text||loading.value)return;messages.value.push({role:'user',text});query.value='';loading.value=true;error.value='';try{const data=(await customerServiceApi.executePlan(text,conversationId.value)).data.data; messages.value.push({role:'assistant',...data}); if(data.customer_service_session_id){ humanSessionId.value=data.customer_service_session_id; sessionStorage.setItem('customer_service_session_id',humanSessionId.value); startPolling() }}catch(e:any){error.value=e.response?.data?.detail?.message||e.message||'客服服务暂时不可用'}finally{loading.value=false}}
</script>
<template><div v-if="visible" class="customer-service-widget"><Transition name="service-pop"><section v-if="open" class="customer-service-panel"><header><div><span>智能客服</span><small>公司业务 · FAQ · 流程 · 政策</small></div><button @click="open=false">×</button></header><div class="service-messages"><p v-if="!messages.length" class="service-welcome">您好，我可以协助查询公司信息、业务流程、常见问题和资料规则。</p><article v-for="(message,index) in messages" :key="index" :class="'service-message '+message.role"><p>{{message.text||message.answer||message.message}}</p><p v-if="message.next_action" class="service-next-action">{{message.next_action}}</p><div v-if="message.data?.latest_asset" class="service-fact-grid"><span>总资产 <b>{{Number(message.data.latest_asset.total_asset).toLocaleString()}}</b></span><span>现金余额 <b>{{Number(message.data.latest_asset.cash_balance).toLocaleString()}}</b></span></div><div v-if="message.data?.items?.length" class="service-fact-items"><span v-for="item in message.data.items" :key="item.id">{{item.ticket_no||item.order_no||item.name||item.product_name}}：{{item.status||item.market_value||''}}</span></div><small v-if="message.ticket_no">已转人工，工单：{{message.ticket_no}} · 会话状态：{{message.customer_service_session_status||'waiting_human'}}</small><div v-if="message.results?.length" class="service-task-results"><span v-for="item in message.results" :key="item.task_id">{{item.intent}}：{{item.status}}</span></div><details v-if="message.citations?.length"><summary>查看参考依据（{{message.citations.length}}）</summary><div v-for="citation in message.citations" :key="citation.chunk_id">{{citation.content}}</div></details></article><p v-if="loading" class="service-typing">正在检索资料…</p></div><p v-if="error" class="error">{{error}}</p><div v-if="humanSessionId" class="service-human-actions"><button @click="customerServiceMessageApi.customerClose(humanSessionId).then(()=>{humanSessionId='';stopPolling()})">结束人工服务</button></div><footer><select v-model="intent"><option v-for="item in options" :key="item.value" :value="item.value">{{item.label}}</option></select><textarea v-model="query" @keydown.enter.exact.prevent="send" placeholder="请输入问题，Enter 发送"/><button :disabled="loading||!query.trim()" @click="send">发送</button></footer></section></Transition><button class="customer-service-bubble" :class="{open}" @click="open=!open" aria-label="打开智能客服"><span>{{open?'×':'✦'}}</span><i>客服</i></button></div></template>
